import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
} from '../remotionShim';
// Font Loader Pattern
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- SCHEMA ---


export type TreadmillRunnersProps = Record<string, any>;

// --- SUB-COMPONENTS ---

/**
 * Reusable Stick Figure Runner
 * Using SVG for limb articulation
 */
const Runner: React.FC<{
  speed: number;
  color: string;
  isFat?: boolean;
  glow?: boolean;
  frame: number;
}> = ({ speed, color, isFat = false, glow = false, frame }) => {
  // Cycle calculation
  const t = frame * speed;

  // Vertical Bounce
  const bounce = Math.abs(Math.cos(t * 2)) * 10;
  const torsoY = 150 - bounce;

  // Limb Angles
  const leftLegAngle = Math.sin(t) * (isFat ? 20 : 35);
  const rightLegAngle = Math.sin(t + Math.PI) * (isFat ? 20 : 35);
  
  // Knee bend logic (simple IK approximation for visual running)
  const leftKneeBend = Math.max(0, Math.sin(t) * 40 + 10);
  const rightKneeBend = Math.max(0, Math.sin(t + Math.PI) * 40 + 10);

  // Arms - opposite to legs
  const leftArmAngle = Math.sin(t + Math.PI) * 30;
  const rightArmAngle = Math.sin(t) * 30;

  const strokeWidth = 12;
  const headSize = 25;

  return (
    <div
      style={{
        width: 300,
        height: 400,
        position: "relative",
        filter: glow ? `drop-shadow(0 0 15px ${color})` : "none",
      }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox="0 0 300 400"
        style={{ overflow: "visible" }}
      >
        <g transform={`translate(150, ${torsoY})`}>
          {/* Head */}
          <circle cx={0} cy={-60} r={headSize} fill={color} />

          {/* Torso */}
          {isFat ? (
            // Single continuous torso with rounded belly
            // Using a thick stroke with a curve to integrate belly and spine
            <path
              d="M 0 -25 Q 15 15 0 60"
              stroke={color}
              strokeWidth={70} // Significantly thicker than head (50px)
              strokeLinecap="round"
              fill="none"
            />
          ) : (
            // Straight line for "Fit" runner
            <line
              x1={0}
              y1={-30}
              x2={0}
              y2={60}
              stroke={color}
              strokeWidth={strokeWidth}
              strokeLinecap="round"
            />
          )}

          {/* Legs Group */}
          <g transform="translate(0, 60)">
            {/* Right Leg (Back) */}
            <g transform={`rotate(${rightLegAngle})`}>
              <line
                x1={0}
                y1={0}
                x2={0}
                y2={60}
                stroke={color}
                strokeWidth={strokeWidth}
                strokeLinecap="round"
              />
              <g transform={`translate(0, 60) rotate(${rightKneeBend})`}>
                <line
                  x1={0}
                  y1={0}
                  x2={0}
                  y2={60}
                  stroke={color}
                  strokeWidth={strokeWidth}
                  strokeLinecap="round"
                />
              </g>
            </g>

            {/* Left Leg (Front) */}
            <g transform={`rotate(${leftLegAngle})`}>
              <line
                x1={0}
                y1={0}
                x2={0}
                y2={60}
                stroke={color}
                strokeWidth={strokeWidth}
                strokeLinecap="round"
              />
              <g transform={`translate(0, 60) rotate(${leftKneeBend})`}>
                <line
                  x1={0}
                  y1={0}
                  x2={0}
                  y2={60}
                  stroke={color}
                  strokeWidth={strokeWidth}
                  strokeLinecap="round"
                />
              </g>
            </g>
          </g>

          {/* Arms Group */}
          <g transform="translate(0, -20)">
            {/* Back Arm (Pumping) */}
            <g transform={`rotate(${rightArmAngle})`}>
              <line
                x1={0}
                y1={0}
                x2={0}
                y2={40}
                stroke={color}
                strokeWidth={strokeWidth}
                strokeLinecap="round"
              />
              <g transform={`translate(0, 40) rotate(-80)`}>
                 <line
                  x1={0}
                  y1={0}
                  x2={0}
                  y2={35}
                  stroke={color}
                  strokeWidth={strokeWidth}
                  strokeLinecap="round"
                />
              </g>
            </g>
             
            {/* Front Arm (Pumping) */}
            <g transform={`rotate(${leftArmAngle})`}>
               <line
                  x1={0}
                  y1={0}
                  x2={0}
                  y2={40}
                  stroke={color}
                  strokeWidth={strokeWidth}
                  strokeLinecap="round"
                />
                <g transform={`translate(0, 40) rotate(-80)`}>
                 <line
                  x1={0}
                  y1={0}
                  x2={0}
                  y2={35}
                  stroke={color}
                  strokeWidth={strokeWidth}
                  strokeLinecap="round"
                />
              </g>
            </g>
          </g>
        </g>
      </svg>
    </div>
  );
};

const Treadmill: React.FC<{ speed: number; frame: number }> = ({
  speed,
  frame,
}) => {
  // Speed of the belt dots (Reversed direction as requested)
  const dashOffset = frame * speed * 20;

  return (
    <div
      style={{
        width: 400,
        height: 200,
        position: "relative",
      }}
    >
      <svg width="100%" height="100%" viewBox="0 0 400 200">
        {/* Belt Base */}
        <rect
          x={20}
          y={140}
          width={360}
          height={40}
          rx={20}
          fill="#444"
        />
        
        {/* Belt Animation (Dotted Line) */}
        <rect
          x={20}
          y={140}
          width={360}
          height={40}
          rx={20}
          fill="none"
          stroke="#fff"
          strokeWidth={3}
          strokeDasharray="10 10"
          strokeDashoffset={dashOffset}
        />
      </svg>
    </div>
  );
};

// --- MAIN COMPONENT ---

const TreadmillRunners: React.FC<TreadmillRunnersProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  leftRunnerSpeed = 0.15,
  rightRunnerSpeed = 0.45,
  leftColor = "#808080",
  rightColor = "#FFFF00",
  day1Text = "DAY 1",
  day365Text = "DAY 365",
}) => {
  // Updated to Playfair Display for a luxurious but minimalistic feel
  useFontLoader(["Playfair Display"]); 
  
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Scene Container Styling
  const sceneWidth = 1000;
  const sceneHeight = 600;
  
  // Center the scene
  const scale = Math.min(width / sceneWidth, height / sceneHeight) * 0.9;
  const xOffset = (width - sceneWidth * scale) / 2;
  const yOffset = (height - sceneHeight * scale) / 2;

  // Vertical shifts to align treadmill with feet
  const treadmillTop = 230; 
  const floorLineTop = 430;
  const reflectionTop = 360;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          width: sceneWidth,
          height: sceneHeight,
          position: "absolute",
          transform: `translate(${xOffset}px, ${yOffset}px) scale(${scale})`,
          transformOrigin: "top left",
        }}
      >
        {/* Main Scene Content */}
        <div style={{ position: "relative", width: "100%", height: "100%" }}>
          
          {/* ---- LEFT RUNNER GROUP ---- */}
          <div
            style={{
              position: "absolute",
              left: 50,
              top: 100,
              width: 400,
              height: 500,
            }}
          >
            {/* Label */}
            <div
              style={{
                position: "absolute",
                top: -50,
                width: "100%",
                textAlign: "center",
                color: "#FFFFFF",
                fontFamily: "'Playfair Display', serif",
                fontSize: 32,
                fontWeight: 700,
                opacity: 0.9,
              }}
            >
              {day1Text}
            </div>

            {/* Runner */}
            <div style={{ position: "absolute", left: 10, top: 40, zIndex: 1 }}>
              <Runner
                speed={leftRunnerSpeed}
                color={leftColor}
                isFat={false}
                frame={frame}
              />
            </div>
            
            {/* Treadmill */}
            <div style={{ position: "absolute", top: treadmillTop, left: 0 }}>
              <Treadmill speed={leftRunnerSpeed} frame={frame} />
            </div>
          </div>

          {/* ---- RIGHT RUNNER GROUP ---- */}
          <div
            style={{
              position: "absolute",
              left: 550,
              top: 100,
              width: 400,
              height: 500,
            }}
          >
             {/* Label */}
             <div
              style={{
                position: "absolute",
                top: -50,
                width: "100%",
                textAlign: "center",
                color: "#FFFFFF",
                fontFamily: "'Playfair Display', serif",
                fontSize: 32,
                fontWeight: 700,
                opacity: 0.9,
              }}
            >
              {day365Text}
            </div>

            {/* Visuals Wrapper - Flipped Horizontally to face Left */}
            <div style={{ width: "100%", height: "100%", transform: "scaleX(-1)" }}>
              {/* Runner */}
              <div style={{ position: "absolute", left: 10, top: 40, zIndex: 1 }}>
                <Runner
                  speed={rightRunnerSpeed}
                  color={rightColor}
                  isFat={false}
                  glow={true}
                  frame={frame}
                />
              </div>

              {/* Treadmill */}
              <div style={{ position: "absolute", top: treadmillTop, left: 0 }}>
                <Treadmill speed={rightRunnerSpeed} frame={frame} />
              </div>
            </div>
          </div>
        </div>

        {/* ---- REFLECTION LAYER ---- */}
        {/* We duplicate the visual elements but flip them and mask them */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            top: reflectionTop, 
            transform: "scaleY(-1)", // Flip vertically
            opacity: 0.2, // Low opacity
            pointerEvents: "none",
            maskImage: "linear-gradient(to top, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 60%)",
            WebkitMaskImage: "linear-gradient(to top, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 60%)",
          }}
        >
          {/* Left Reflection */}
          <div style={{ position: "absolute", left: 50, top: 100 }}>
             <div style={{ position: "absolute", left: 10, top: 40 }}>
              <Runner
                speed={leftRunnerSpeed}
                color={leftColor}
                isFat={false}
                frame={frame}
              />
            </div>
            <div style={{ position: "absolute", top: treadmillTop, left: 0 }}>
              <Treadmill speed={leftRunnerSpeed} frame={frame} />
            </div>
          </div>

          {/* Right Reflection - Flipped Horizontally */}
          <div 
            style={{ 
              position: "absolute", 
              left: 550, 
              top: 100, 
              width: 400, 
              height: 500, 
              transform: "scaleX(-1)" 
            }}
          >
             <div style={{ position: "absolute", left: 10, top: 40 }}>
              <Runner
                speed={rightRunnerSpeed}
                color={rightColor}
                isFat={false}
                glow={true}
                frame={frame}
              />
            </div>
            <div style={{ position: "absolute", top: treadmillTop, left: 0 }}>
              <Treadmill speed={rightRunnerSpeed} frame={frame} />
            </div>
          </div>
        </div>
        
        {/* Floor Line Connector */}
         <div style={{
             position: 'absolute',
             top: floorLineTop,
             left: 450,
             width: 100,
             height: 2,
             backgroundColor: '#555',
         }} />

      </div>
    </AbsoluteFill>
  );
};

export default TreadmillRunners;